    demo_credentials = OAuthCredentials(
        consumer_key="consumer-key",
        consumer_secret="consumer-secret",
        token="access-token",
        token_secret="token-secret",
    )

    header = sign_request("GET", "https://api.example.com/resource", demo_credentials)
    print(header)

